import { MakeLogicType, actions, kea, path } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import api from 'lib/api'
import { ApiError, shouldReportApiFailure } from 'lib/api-error'

export interface Response {
    query: string
    trace_id: string
    error?: string
}

// Copy shown when the fixer request fails before the backend can return its own message.
const FIXER_UNAVAILABLE_MESSAGE = 'The AI query fixer is unavailable right now.'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface fixSQLErrorsLogicValues {
    response: Response | null
    responseLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface fixSQLErrorsLogicActions {
    fixErrors: (
        query: string,
        error?: string,
        connectionId?: string
    ) => {
        connectionId: string | undefined
        error: string | undefined
        query: string
    }
    fixErrorsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    fixErrorsSuccess: (
        response: Response,
        payload?: {
            connectionId: string | undefined
            error: string | undefined
            query: string
        }
    ) => {
        response: Response
        payload?: {
            connectionId: string | undefined
            error: string | undefined
            query: string
        }
    }
}

export type fixSQLErrorsLogicType = MakeLogicType<fixSQLErrorsLogicValues, fixSQLErrorsLogicActions>

export const fixSQLErrorsLogic = kea<fixSQLErrorsLogicType>([
    path(['scenes', 'data-warehouse', 'editor', 'fixSQLErrorsLogic']),
    actions({
        fixErrors: (query: string, error?: string, connectionId?: string) => ({ query, error, connectionId }),
    }),
    loaders({
        response: [
            null as Response | null,
            {
                fixErrors: async ({ query, error, connectionId }) => {
                    try {
                        const response = await api.fixHogQLErrors.fix(query, error, connectionId)

                        return response as Response
                    } catch (e) {
                        // A { trace_id, error } 400 is the backend's own "fixer can't run" message
                        // (missing LLM credentials, provider outage) — surface it as a normal
                        // response. Report anything else (a 500 from outside the backend try, a
                        // throttle, a dropped request) to error tracking first, using the shared
                        // policy, so the catch degrades the expected case without hiding a genuine
                        // fault.
                        const apiError = e instanceof ApiError ? e : null
                        if (apiError?.status !== 400 && shouldReportApiFailure(e)) {
                            posthog.captureException(e)
                        }
                        return {
                            query: '',
                            trace_id: apiError?.data?.trace_id ?? '',
                            error: apiError?.data?.error ?? FIXER_UNAVAILABLE_MESSAGE,
                        }
                    }
                },
            },
        ],
    }),
])
